# Agent Specialization Manager demo: profile match scoring with load awareness.
AGENTS={"a1":{"domains":{"translation":0.9,"summarization":0.5},"load":2},
        "a2":{"domains":{"translation":0.6,"summarization":0.95},"load":0},
        "a3":{"domains":{"translation":0.7},"load":5}}
def route(task_domain):
    scored=[]
    for name,a in AGENTS.items():
        fit=a["domains"].get(task_domain,0)
        if fit<0.5: continue
        scored.append((round(fit-0.05*a["load"],3),name,fit))
    return sorted(scored,reverse=True)
print("translation task ->",route("translation"))
print("summarization task ->",route("summarization"))

